    { "id": "perguntas-frequentes", "objetivo": "Responder dúvidas recorrentes", "requisitos": ["RF-07"] },
    { "id": "rodape", "objetivo": "Contato, mapa e redes sociais", "requisitos": ["RF-08"] }
  ]
}

import { useState } from "react";

const cursos = [
  { id: "farmacia", tipo: "Técnico", nome: "Técnico em Farmácia" },
  { id: "cuidador", tipo: "Profissionalizante", nome: "Cuidador de Idosos" },
];

export default function LandingMvp() {
  const [dados, setDados] = useState({ nome: "", email: "", curso: cursos[0].id, aceite: false });
  const [status, setStatus] = useState("idle");
  const emailValido = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(dados.email);
  const podeEnviar = dados.nome.trim() && emailValido && dados.aceite;

  async function enviar(e) {
    e.preventDefault();
    setStatus("enviando");
    const r = await fetch("https://exemplo-servico-de-formulario.com/f/SEU_ID", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(dados),
    });
    setStatus(r.ok ? "ok" : "erro");
  }

  if (status === "ok") return <p>Recebemos seu interesse. Entraremos em contato.</p>;

  return (
    <main>
      <h1>Instituto Aurora de Educação em Saúde</h1>
      <ul>{cursos.map((c) => <li key={c.id}>{c.tipo}: {c.nome}</li>)}</ul>
      <form onSubmit={enviar}>
        <label>Nome <input value={dados.nome} onChange={(e) => setDados({ ...dados, nome: e.target.value })} /></label>
        <label>E-mail <input type="email" value={dados.email} onChange={(e) => setDados({ ...dados, email: e.target.value })} /></label>
        {dados.email && !emailValido && <span role="alert">Informe um e-mail válido</span>}
        <label>Curso
          <select value={dados.curso} onChange={(e) => setDados({ ...dados, curso: e.target.value })}>
            {cursos.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
          </select>
        </label>
        <label><input type="checkbox" checked={dados.aceite} onChange={(e) => setDados({ ...dados, aceite: e.target.checked })} /> Li e aceito a política de privacidade</label>
        <button disabled={!podeEnviar || status === "enviando"}>Quero ser avisado</button>
        {status === "erro" && <p role="alert">Não foi possível enviar. Tente pelo telefone do rodapé.</p>}
      </form>
    </main>
  );
}
